package com.example;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class App {

    private static final Logger log = LoggerFactory.getLogger(App.class);

    public static void main(String[] args) {
        log.info("Application starting");
        Greeter greeter = new Greeter();
        log.info(greeter.greet("World"));
        log.debug("Debug detail only visible when enabled");
        log.info("Application finished");
    }
}

package com.example;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class Greeter {

    private static final Logger log = LoggerFactory.getLogger(Greeter.class);

    public String greet(String name) {
        log.debug("Building greeting for {}", name);
        return "Hello, " + name + "!";
    }
}

package com.example;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.Test;

class AppTest {

    @Test
    void greetReturnsPersonalizedMessage() {
        assertEquals("Hello, World!", new Greeter().greet("World"));
    }
}
